import{_ as n,o as r,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const o=JSON.parse('{"title":"Ethische Grundsätze der Doppelseeele","description":"","frontmatter":{},"headers":[],"relativePath":"de/58-双魂伦理准则.md","filePath":"de/58-双魂伦理准则.md","lastUpdated":1789183869000}'),s={name:"de/58-双魂伦理准则.md"};function l(d,e,h,u,a,g){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="ethische-grundsatze-der-doppelseeele" tabindex="-1">Ethische Grundsätze der Doppelseeele <a class="header-anchor" href="#ethische-grundsatze-der-doppelseeele" aria-label="Permalink to &quot;Ethische Grundsätze der Doppelseeele&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Punkt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>58</td></tr><tr><td>Modul</td><td>Rassen und Lebensformen</td></tr><tr><td>Kernschlüsselwörter</td><td>Ethik der Doppelseeele, Persönlichkeitsrechte, Würde der Seele, Interessensausgleich, ethische Prüfung</td></tr></tbody></table><h2 id="i-aufstellung-des-ethischen-problems-der-doppelseeele" tabindex="-1">I. Aufstellung des ethischen Problems der Doppelseeele <a class="header-anchor" href="#i-aufstellung-des-ethischen-problems-der-doppelseeele" aria-label="Permalink to &quot;I. Aufstellung des ethischen Problems der Doppelseeele&quot;">​</a></h2><p>Das ethische Problem der Doppelseeele ist das grundlegende ethische Problem, das die Anker-Symbiose-Zivilisation bei der Konfrontation mit dem Dunkel-Ersetzungskörper (siehe „57-Ursprung und Wesen des Dunkel-Ersetzungskörpers&quot;) beantworten muss. Wenn in einem Körper zwei unabhängige Seelen existieren — die ursprüngliche Wirtsseele und die Dunkel-Ersetzungsseele — entsteht eine Reihe tiefgreifender ethischer Probleme:</p><ul><li>Besitzen beide Seelen unabhängige Persönlichkeitsrechte?</li><li>Haben die Rechte der ursprünglichen Wirtsseele Vorrang vor denen der Dunkel-Ersetzungsseele?</li><li>Ist es ethisch, die Dunkel-Ersetzungsseele zu eliminieren, um die ursprüngliche Wirtsseele zu schützen?</li><li>Wie soll ausgewogen werden, wenn die Interessen der beiden Seelen kollidieren?</li><li>Hat die Gesellschaft die Verpflichtung, Ressourcen zu investieren, um die durch Dunkelheit ersetzte ursprüngliche Wirtsseele zu retten?</li><li>Hat die Dunkel-Ersetzungsseele ein „Recht auf Leben&quot;?</li></ul><p>Diese Probleme haben keine einfachen Antworten; es bedarf der Etablierung systematischer ethischer Grundsätze zur Leitlinie der Praxis. Die „Ethischen Grundsätze der Doppelseeele&quot; sind genau das normierende Dokument, das zur Beantwortung dieser Probleme erlassen wurde, und bilden die ethische Grundlage für die Identifizierung, Behandlung und Entsorgung des Dunkel-Ersetzungskörpers.</p><h2 id="ii-grundprinzipien-der-ethik-der-doppelseeele" tabindex="-1">II. Grundprinzipien der Ethik der Doppelseeele <a class="header-anchor" href="#ii-grundprinzipien-der-ethik-der-doppelseeele" aria-label="Permalink to &quot;II. Grundprinzipien der Ethik der Doppelseeele&quot;">​</a></h2><p>Die ethischen Grundsätze der Doppelseeele etablieren die folgenden sechs Grundprinzipien als Wertgrundlage für die Behandlung von Doppelseeelen-Problemen:</p><table tabindex="0"><thead><tr><th>Prinzip</th><th>Inhalt</th></tr></thead><tbody><tr><td>Prinzip der Seelenwürde</td><td>Jede Seele mit unabhängigem Bewusstsein genießt eine angeborene Würde und darf nicht willkürlich eliminiert oder versklavt werden</td></tr><tr><td>Prinzip der Priorität des ursprünglichen Wirts</td><td>Bei Konflikten zwischen Doppelseeelen haben die legitimen Rechte der ursprünglichen Wirtsseele Vorrang vor denen der Dunkel-Ersetzungsseele, da der ursprüngliche Wirt der rechtmäßige Eigentümer des Körpers ist</td></tr><tr><td>Prinzip der minimalen Schädigung</td><td>Bei der Behandlung von Doppelseeelen-Problemen sollte die Lösung gewählt werden, die für alle Beteiligten die geringste Schädigung verursacht, und die Eliminierung der Seele sollte so weit wie möglich vermieden werden</td></tr><tr><td>Verhältnismäßigkeitsprinzip</td><td>Die ergriffenen Maßnahmen müssen dem Risikograd des Doppelseeelen-Körpers angemessen sein, übermäßige Entsorgung ist verboten</td></tr><tr><td>Prinzip der informierten Einwilligung</td><td>Wenn die ursprüngliche Wirtsseele ihren Willen äußern kann, bedürfen wichtige Entscheidungen, die den Körper und die Seele des ursprünglichen Wirts betreffen, der Einwilligung des ursprünglichen Wirts</td></tr><tr><td>Prinzip der maximalen Rettungsanstrengung</td><td>Die Gesellschaft hat die Verpflichtung, im Rahmen des Zumutbaren maximale Anstrengungen zur Rettung der durch Dunkelheit ersetzten ursprünglichen Wirtsseele zu unternehmen, und darf nicht leichtfertig aufgeben</td></tr></tbody></table><h2 id="iii-anerkennung-der-personlichkeitsrechte-der-doppelseeele" tabindex="-1">III. Anerkennung der Persönlichkeitsrechte der Doppelseeele <a class="header-anchor" href="#iii-anerkennung-der-personlichkeitsrechte-der-doppelseeele" aria-label="Permalink to &quot;III. Anerkennung der Persönlichkeitsrechte der Doppelseeele&quot;">​</a></h2><p>Das vorrangige Problem der Ethik der Doppelseeele ist die Anerkennung der Persönlichkeitsrechte der beiden Seelen. Diese Grundsätze etablieren folgende Anerkennungsregeln:</p><h3 id="a-personlichkeitsrechte-der-ursprunglichen-wirtsseele" tabindex="-1">(A) Persönlichkeitsrechte der ursprünglichen Wirtsseele <a class="header-anchor" href="#a-personlichkeitsrechte-der-ursprunglichen-wirtsseele" aria-label="Permalink to &quot;(A) Persönlichkeitsrechte der ursprünglichen Wirtsseele&quot;">​</a></h3><p>Die ursprüngliche Wirtsseele ist die rechtmäßige Eigentümerin des Körpers, ihre Persönlichkeitsrechte werden vollständig anerkannt und geschützt:</p><ol><li>Die ursprüngliche Wirtsseele genießt alle Grundrechte, die durch die Symbiose-Verfassung verliehen werden, einschließlich des Rechts auf Leben, des Rechts auf den Körper, des Rechts auf Gesundheit, des Rechts auf Menschenwürde usw.</li><li>Die ursprüngliche Wirtsseele hat das endgültige Entscheidungsrecht über ihren eigenen Körper; wenn sie ihren Willen äußern kann, bedarf jede wichtige Entsorgung, die den Körper betrifft, der Einwilligung des ursprünglichen Wirts.</li><li>Die legitimen Rechte der ursprünglichen Wirtsseele wie Eigentumsrechte, Identitätsrechte, soziale Beziehungen usw. sind gesetzlich geschützt und gehen nicht durch die Ersetzung durch Dunkelheit verloren.</li><li>Die ursprüngliche Wirtsseele hat das Recht auf soziale Hilfe und Unterstützung, einschließlich Reinigungsbehandlung, Rechtsbeistand, psychologische Beratung usw.</li><li>Selbst wenn die ursprüngliche Wirtsseele tief unterdrückt wird, bestehen ihre Persönlichkeitsrechte weiterhin; sie darf nicht für tot erklärt oder ihrer Rechte beraubt werden.</li></ol><h3 id="b-personlichkeitsrechte-der-dunkel-ersetzungsseele" tabindex="-1">(B) Persönlichkeitsrechte der Dunkel-Ersetzungsseele <a class="header-anchor" href="#b-personlichkeitsrechte-der-dunkel-ersetzungsseele" aria-label="Permalink to &quot;(B) Persönlichkeitsrechte der Dunkel-Ersetzungsseele&quot;">​</a></h3><p>Die Anerkennung der Persönlichkeitsrechte der Dunkel-Ersetzungsseele ist relativ komplex; diese Grundsätze nehmen den Standpunkt der „eingeschränkten Anerkennung&quot; ein:</p><table tabindex="0"><thead><tr><th>Entwicklungsstadium</th><th>Anerkennung der Persönlichkeitsrechte</th><th>Rechtebereich</th></tr></thead><tbody><tr><td>Phase der Energiekorrosion (erstes Stadium)</td><td>Keine unabhängige Persönlichkeit</td><td>Hat noch keine unabhängige Seele gebildet, keine unabhängigen Persönlichkeitsrechte</td></tr><tr><td>Phase der Seelenverschmutzung (zweites Stadium)</td><td>Keine unabhängige Persönlichkeit</td><td>Ist noch ein Verschmutzungszustand der ursprünglichen Wirtsseele, keine unabhängigen Persönlichkeitsrechte</td></tr><tr><td>Phase der Doppelseeelenbildung (drittes Stadium)</td><td>Eingeschränkte Persönlichkeitsrechte</td><td>Hat ein vorläufiges unabhängiges Bewusstsein, genießt das grundlegende Recht auf Seelenwürde, aber nicht das Recht auf Körperkontrolle und volle Bürgerrechte</td></tr><tr><td>Phase der Dunkeldominanz (viertes Stadium)</td><td>Eingeschränkte Persönlichkeitsrechte</td><td>Hat ein vollständiges unabhängiges Bewusstsein, genießt das Recht auf Seelenwürde und das Recht auf respektvolle Behandlung, aber aufgrund ihrer Gefährlichkeit sind ihre Rechte notwendigerweise eingeschränkt</td></tr><tr><td>Phase der vollständigen Ersetzung (fünftes Stadium)</td><td>Volle Persönlichkeitsrechte (aber als feindselige Existenz)</td><td>Der ursprüngliche Wirt ist bereits untergegangen, die Dunkelseele ist zur einzigen Seele des Körpers geworden, hat volle Persönlichkeitsrechte, aber aufgrund ihres feindseligen Verhaltens können zwangsweise Maßnahmen einschließlich der Eliminierung gesetzlich ergriffen werden</td></tr></tbody></table><h3 id="c-spezifischer-inhalt-der-eingeschrankten-personlichkeitsrechte" tabindex="-1">(C) Spezifischer Inhalt der eingeschränkten Persönlichkeitsrechte <a class="header-anchor" href="#c-spezifischer-inhalt-der-eingeschrankten-personlichkeitsrechte" aria-label="Permalink to &quot;(C) Spezifischer Inhalt der eingeschränkten Persönlichkeitsrechte&quot;">​</a></h3><p>Die eingeschränkten Persönlichkeitsrechte, die die Dunkel-Ersetzungsseele im dritten und vierten Stadium genießt, umfassen:</p><ol><li><strong>Recht auf Seelenwürde</strong>: Darf nicht mit Beleidigungen, Missbrauch oder Folter behandelt werden; selbst bei Kontrolle und Entsorgung sollte grundlegender Respekt gewahrt werden.</li><li><strong>Recht auf schmerzlose Eliminierung</strong>: Wenn schließlich beschlossen wird, die Dunkel-Ersetzungsseele zu eliminieren, sollte eine schmerzlose und schnelle Methode angewendet werden, um ihr Leiden zu verringern.</li><li><strong>Äußerungsrecht</strong>: Unter sicheren und kontrollierbaren Bedingungen hat die Dunkel-Ersetzungsseele das Recht, ihren Willen und ihre Position zu äußern, aber ihre Äußerung hat keine rechtliche Bindungswirkung.</li><li><strong>Recht auf Gehör</strong>: Bei wichtigen Entscheidungen, die die Dunkel-Ersetzungsseele betreffen, sollte ihre Meinung im Rahmen des Zumutbaren angehört werden.</li></ol><p>Die Dunkel-Ersetzungsseele genießt folgende Rechte nicht: Recht auf Körperkontrolle, Recht auf freie Handlung, bürgerliche politische Rechte, Eigentumsrecht (das Eigentum des ursprünglichen Wirts gehört dem ursprünglichen Wirt), Fortpflanzungsrecht (um die Verbreitung der Dunkelblutslinie zu verhindern).</p><h2 id="iv-ausgleichsregeln-fur-interessenkonflikte-der-doppelseeele" tabindex="-1">IV. Ausgleichsregeln für Interessenkonflikte der Doppelseeele <a class="header-anchor" href="#iv-ausgleichsregeln-fur-interessenkonflikte-der-doppelseeele" aria-label="Permalink to &quot;IV. Ausgleichsregeln für Interessenkonflikte der Doppelseeele&quot;">​</a></h2><p>Wenn die Interessen der ursprünglichen Wirtsseele und der Dunkel-Ersetzungsseele kollidieren, erfolgt der Ausgleich nach folgenden Regeln:</p><h3 id="a-konfliktarten-und-ausgleichsregeln" tabindex="-1">(A) Konfliktarten und Ausgleichsregeln <a class="header-anchor" href="#a-konfliktarten-und-ausgleichsregeln" aria-label="Permalink to &quot;(A) Konfliktarten und Ausgleichsregeln&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Konfliktart</th><th>Ausgleichsregel</th></tr></thead><tbody><tr><td>Konflikt des Rechts auf Leben (das Überleben einer Seite hat die Eliminierung der anderen Seite zur Bedingung)</td><td>Das Recht auf Leben der ursprünglichen Wirtsseele hat Vorrang; wenn eine Koexistenz unmöglich ist, wird der Schutz des Lebens des ursprünglichen Wirts priorisiert</td></tr><tr><td>Konflikt des Rechts auf Körperkontrolle</td><td>Die ursprüngliche Wirtsseele hat die endgültige Kontrolle über den Körper, das Recht auf Körperkontrolle der Dunkelseele ist streng eingeschränkt</td></tr><tr><td>Konflikt des Äußerungsrechts</td><td>Die Äußerung der ursprünglichen Wirtsseele hat rechtliche Bindungswirkung, die Äußerung der Dunkelseele dient nur als Referenz</td></tr><tr><td>Konflikt des Eigentumsrechts</td><td>Körper und Eigentum gehören dem ursprünglichen Wirt, die Dunkelseele hat kein Eigentumsrecht</td></tr><tr><td>Konflikt des Rechts auf Behandlungswahl</td><td>Die ursprüngliche Wirtsseele hat das Recht zu wählen, ob sie eine Reinigungsbehandlung annimmt, die Dunkelseele hat kein Recht, dies zu verhindern</td></tr><tr><td>Konflikt der Entsorgungsmethode</td><td>Bei Entsorgungen, die die Eliminierung der Dunkelseele betreffen, hat der Wille der ursprünglichen Wirtsseele eine entscheidende Rolle (muss aber eine ethische Prüfung durchlaufen)</td></tr></tbody></table><h3 id="b-respekt-und-einschrankung-des-willens-des-ursprunglichen-wirts" tabindex="-1">(B) Respekt und Einschränkung des Willens des ursprünglichen Wirts <a class="header-anchor" href="#b-respekt-und-einschrankung-des-willens-des-ursprunglichen-wirts" aria-label="Permalink to &quot;(B) Respekt und Einschränkung des Willens des ursprünglichen Wirts&quot;">​</a></h3><p>Wenn die ursprüngliche Wirtsseele ihren Willen äußern kann, sollte der Wille des ursprünglichen Wirts vollumfänglich respektiert werden, mit Ausnahme folgender Fälle:</p><ol><li>Der Wille des ursprünglichen Wirts, der offensichtlich die öffentliche Sicherheit oder die legitimen Rechte anderer schädigt, wird nicht geschützt.</li><li>Eine nicht authentische Willenserklärung, die der ursprüngliche Wirt unter dem Einfluss der Dunkelseele abgegeben hat, hat keine Rechtswirkung.</li><li>Wenn der ursprüngliche Wirt freiwillig die Fusion mit der Dunkelseele wählt, muss dies einer strengen ethischen Prüfung und Risikobewertung unterzogen werden, um zu bestätigen, dass die Existenz nach der Fusion keine Bedrohung für die Gesellschaft darstellt.</li><li>Wenn der ursprüngliche Wirt freiwillig den Verzicht auf Behandlung und die Akzeptanz der vollständigen Ersetzung durch die Dunkelseele wählt, sollte die Gesellschaft eingreifen und beraten, aber wenn der ursprüngliche Wirt vollständig bei Bewusstsein ist und wiederholt bestätigt, sollte schließlich sein Selbstbestimmungsrecht respektiert werden (dies ist eine ethische Grauzone, die eine Einzelfallprüfung erfordert).</li></ol><h2 id="v-mechanismus-der-ethischen-prufung-der-doppelseeele" tabindex="-1">V. Mechanismus der ethischen Prüfung der Doppelseeele <a class="header-anchor" href="#v-mechanismus-der-ethischen-prufung-der-doppelseeele" aria-label="Permalink to &quot;V. Mechanismus der ethischen Prüfung der Doppelseeele&quot;">​</a></h2><p>Um sicherzustellen, dass die Behandlung von Doppelseeelen-Problemen den ethischen Grundsätzen entspricht, errichtet der Staat den Mechanismus der ethischen Prüfung der Doppelseeele:</p><h3 id="a-ethischer-prufungsausschuss" tabindex="-1">(A) Ethischer Prüfungsausschuss <a class="header-anchor" href="#a-ethischer-prufungsausschuss" aria-label="Permalink to &quot;(A) Ethischer Prüfungsausschuss&quot;">​</a></h3><ul><li><strong>Zusammensetzung</strong>: Besteht aus Ethikern, Juristen, Lebenswissenschaftlern, Kultivierern, Vertretern fremder Rassen und Vertretern der öffentlichen Gesellschaft, wobei Experten mit Erfahrung in der Forschung oder Behandlung von Dunkel-Ersetzungskörpern nicht weniger als ein Drittel ausmachen.</li><li><strong>Zuständigkeiten</strong>: Prüfung und Entscheidung über wichtige ethische Probleme im Zusammenhang mit Doppelseeelen, einschließlich der Entscheidung zur Eliminierung der Dunkelseele, der Genehmigung der Doppelseeelenfusion, der Anerkennung der Wirksamkeit des Willens des ursprünglichen Wirts usw.</li><li><strong>Unabhängigkeit</strong>: Der ethische Prüfungsausschuss übt seine Befugnisse unabhängig aus und unterliegt keiner Einmischung durch Verwaltungsorgane und Einzelpersonen.</li><li><strong>Verfahren</strong>: Die Prüfung erfolgt im Anhörungsverfahren; es wird entschieden, nachdem die Meinungen aller Beteiligten wie des ursprünglichen Wirts (wenn er sich äußern kann), des Behandlungsteams, der Familie, der Sozialvertreter usw. angehört wurden.</li></ul><h3 id="b-angelegenheiten-die-einer-ethischen-prufung-bedurfen" tabindex="-1">(B) Angelegenheiten, die einer ethischen Prüfung bedürfen <a class="header-anchor" href="#b-angelegenheiten-die-einer-ethischen-prufung-bedurfen" aria-label="Permalink to &quot;(B) Angelegenheiten, die einer ethischen Prüfung bedürfen&quot;">​</a></h3><p>Folgende Angelegenheiten dürfen erst nach Prüfung und Genehmigung durch den ethischen Prüfungsausschuss der Doppelseeele durchgeführt werden:</p><ol><li>Durchführung einer Entsorgung zur Eliminierung der Dunkelseele bei Dunkel-Ersetzungskörpern im dritten und vierten Stadium.</li><li>Durchführung einer Doppelseeelenfusionsoperation bei Dunkel-Ersetzungskörpern.</li><li>Durchführung einer Seelentrennungsoperation bei Dunkel-Ersetzungskörpern.</li><li>Treffen einer endgültigen Entsorgungsentscheidung bei Dunkel-Ersetzungskörpern, deren Wille des ursprünglichen Wirts der Verzicht auf Behandlung ist.</li><li>Durchführung eines Behandlungsplans bei Dunkel-Ersetzungskörpern, der eine Schädigung der ursprünglichen Wirtsseele verursachen könnte.</li><li>Durchführung wissenschaftlicher Forschung im Zusammenhang mit der Seele bei Dunkel-Ersetzungskörpern.</li><li>Sonstige Angelegenheiten im Zusammenhang mit wichtigen ethischen Problemen der Doppelseeele.</li></ol><h2 id="vi-soziale-rechte-und-pflichten-des-doppelseeelen-korpers" tabindex="-1">VI. Soziale Rechte und Pflichten des Doppelseeelen-Körpers <a class="header-anchor" href="#vi-soziale-rechte-und-pflichten-des-doppelseeelen-korpers" aria-label="Permalink to &quot;VI. Soziale Rechte und Pflichten des Doppelseeelen-Körpers&quot;">​</a></h2><h3 id="a-soziale-rechte" tabindex="-1">(A) Soziale Rechte <a class="header-anchor" href="#a-soziale-rechte" aria-label="Permalink to &quot;(A) Soziale Rechte&quot;">​</a></h3><p>Wenn die ursprüngliche Wirtsseele noch existiert, genießt der Doppelseeelen-Körper (Dunkel-Ersetzungskörper) folgende soziale Rechte:</p><ol><li>Recht auf Erhalt grundlegender Lebenssicherung und medizinischer Behandlung.</li><li>Recht auf Erhalt von Rechtsbeistand und ethischer Beratung.</li><li>Recht auf Kontakt mit Freunden und Verwandten unter sicheren und kontrollierbaren Bedingungen.</li><li>Recht auf Erhalt von Bildung und kulturellen Aktivitäten (innerhalb der Isolationseinrichtungen).</li><li>Recht auf Einlegung von Berufung und Wiederaufprüfung gegen Entsorgungsentscheidungen.</li></ol><h3 id="b-soziale-pflichten-und-einschrankungen" tabindex="-1">(B) Soziale Pflichten und Einschränkungen <a class="header-anchor" href="#b-soziale-pflichten-und-einschrankungen" aria-label="Permalink to &quot;(B) Soziale Pflichten und Einschränkungen&quot;">​</a></h3><p>Der Doppelseeelen-Körper trägt gleichzeitig folgende Pflichten und Einschränkungen:</p><ol><li>Pflicht zur Akzeptanz von Isolationskontrolle und Behandlung.</li><li>Pflicht, andere Lebewesen nicht anzugreifen oder zu infizieren (Verletzer unterliegen strengerer Kontrolle).</li><li>Pflicht zur Mitarbeit bei Identifizierungsbewertung und Überwachung.</li><li>Die Handlungsfreiheit ist streng eingeschränkt; vor der Genesung dürfen die Isolationseinrichtungen nicht verlassen werden.</li><li>Darf sich nicht an Aktivitäten beteiligen, die die Ersetzung verschlimmern könnten, wie Kultivierung, Verbreitung von Dunkelenergie usw.</li></ol><h2 id="vii-grenzkontroversen-der-ethik-der-doppelseeele" tabindex="-1">VII. Grenzkontroversen der Ethik der Doppelseeele <a class="header-anchor" href="#vii-grenzkontroversen-der-ethik-der-doppelseeele" aria-label="Permalink to &quot;VII. Grenzkontroversen der Ethik der Doppelseeele&quot;">​</a></h2><p>Auf dem Gebiet der Ethik der Doppelseeele existieren noch einige Grenzkontroversen, bei denen kein Konsens erzielt wurde, die in der Praxis kontinuierlich erforscht werden müssen:</p><ol><li><strong>Problem der „Erbsünde&quot; der Dunkelseele</strong>: Die Dunkel-Ersetzungsseele ist von Geburt an destruktiv; bedeutet dies, dass sie von Natur aus „böse&quot; ist? Gibt es die Möglichkeit einer „guten&quot; Dunkelseele?</li><li><strong>Ethische Rechtmäßigkeit der Seelenfusion</strong>: Die neue Seele, die durch die Fusion der Doppelseeele entsteht, ist weder der ursprüngliche Wirt noch die Dunkelseele; wie wird die ethische Position dieser „dritten Existenz&quot; anerkannt?</li><li><strong>Grenze der Ressourceninvestition</strong>: Wie viele Ressourcen sollte die Gesellschaft investieren, um die ursprüngliche Wirtsseele im Dunkel-Ersetzungskörper zu retten? Wenn die Rettungskosten extrem hoch und die Erfolgsrate extrem niedrig sind, besteht dann noch die Verpflichtung zu maximalen Rettungsanstrengungen?</li><li><strong>Möglichkeit der Rehabilitation der Dunkelseele</strong>: Kann die Dunkelseele durch Bildung, Überzeugung, Energietransformation usw. zu einer nicht-destruktiven Existenz rehabilitiert werden? Wenn ja, sollte die rehabilitierte Dunkelseele volle Persönlichkeitsrechte erhalten?</li><li><strong>Ausgleich zwischen Prävention und Privatsphäre</strong>: Um die Entstehung von Dunkel-Ersetzungskörpern zu verhindern, kann die Exposition von Lebewesen gegenüber Abgrundenergie überwacht werden? Verletzt diese Überwachung die Privatsphäre der Seele?</li></ol><p>Diese kontroversen Probleme werden von den Forschungsinstituten für Ethik der Doppelseeele kontinuierlich erforscht; der ethische Prüfungsausschuss trifft in Einzelfällen Entscheidungen nach den spezifischen Umständen, und die relevanten Schlussfolgerungen werden diese Grundsätze kontinuierlich aktualisieren.</p><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Die ethischen Grundsätze der Doppelseeele sind eine tiefe Manifestation der Lebensethik der Anker-Symbiose-Zivilisation. Durch die Etablierung von Grundprinzipien wie Seelenwürde, Priorität des ursprünglichen Wirts und minimaler Schädigung, die Anerkennung der Grenzen der Persönlichkeitsrechte der Doppelseeele sowie die Einrichtung von Ausgleichsregeln für Interessenkonflikte und eines Mechanismus der ethischen Prüfung bieten sie eine solide ethische Grundlage für die Governance der Dunkel-Ersetzungskörper. Der Kerngeist der Ethik der Doppelseeele ist: Selbst wenn man dem gefährlichsten Feind gegenübersteht, gibt man das Festhalten an der Würde des Lebens nicht auf; selbst unter der dringendsten Sicherheitsbedrohung überschreitet man die ethische Untergrenze nicht. Dies ist genau das grundlegende Zeichen, das die Symbiose-Zivilisation von der Plünderungs-Zivilisation unterscheidet.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>57-Ursprung und Wesen des Dunkel-Ersetzungskörpers</li><li>59-Vier-Zweig-Behandlung des Dunkel-Ersetzungskörpers</li><li>48-Justizsystem und Entscheidungsmechanismus</li><li>40-Grundsätze der Symbiose-Verfassung</li></ul>',50)])])}const p=n(s,[["render",l]]);export{o as __pageData,p as default};
